// 📁 src/pages/public/Postuler.jsx
import { useState, useEffect } from "react";
import { useParams, Link, useNavigate } from "react-router-dom";
import { AnimatePresence, motion } from "framer-motion";
import api from "@/utils/api";

export default function Postuler() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [offre, setOffre] = useState(null);
  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    nom: "",
    email: "",
    telephone: "",
    lien: "",
    commentaire: "",
    cv: null,
    lettre: null,
    diplome: null,
  });

  useEffect(() => {
    api.get(`/recrutement/${id}`)
      .then((res) => setOffre(res.data))
      .catch(() => {});
  }, [id]);

  const handleChange = (e) => {
    const { name, value, files } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: files ? files[0] : value,
    }));
  };

  const validateStep = () => {
    if (step === 1 && (!formData.nom.trim() || !formData.email.trim())) {
      alert("Nom et Email sont obligatoires.");
      return false;
    }
    if (step === 2 && (!formData.telephone.trim() || !formData.lien.trim())) {
      alert("Téléphone et Lien sont requis.");
      return false;
    }
    if (step === 3 && (!formData.cv || !formData.lettre || !formData.diplome)) {
      alert("Veuillez télécharger tous les fichiers requis.");
      return false;
    }
    return true;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    const form = new FormData();
    Object.entries(formData).forEach(([key, val]) => form.append(key, val));
    form.append("offre_id", id);
    try {
      await api.post("/candidatures", form);
        alert("Candidature envoyée avec succès !");
        navigate("/offres");
    } catch (err) {
        const message = await err?.response?.data?.error || "Erreur lors de l’envoi de la candidature.";
        alert("⛔ " + message);
        console.error("❌ Candidature erreur :", err);
    } finally {
      setLoading(false);
    }
  };

  const renderFilePreview = (file) =>
    file ? <p className="text-sm text-gray-600 mt-1">✅ {file.name}</p> : null;

  const ProgressBar = () => (
    <div className="w-full h-2 bg-gray-200 rounded">
      <div
        className={`h-2 rounded transition-all duration-300 ${
          step === 1 ? "w-1/3 bg-red-500" : step === 2 ? "w-2/3 bg-orange-500" : "w-full bg-green-600"
        }`}
      />
    </div>
  );

  return (
    <div className="max-w-2xl mx-auto px-4 py-24">
      <h1 className="text-2xl font-bold text-red-700 mb-4 pt-10">
        Postuler à : {offre?.titre}
      </h1>

      <form onSubmit={handleSubmit} className="space-y-6">
        <ProgressBar />
        <AnimatePresence mode="wait">
          {step === 1 && (
            <motion.div
              key="step1"
              initial={{ opacity: 0, x: -30 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: 30 }}
              transition={{ duration: 0.3 }}
              className="space-y-4"
            >
              <div>
                <label className="block">Nom *</label>
                <input type="text" name="nom" value={formData.nom} onChange={handleChange} required className="w-full border rounded p-2" />
              </div>
              <div>
                <label className="block">Email *</label>
                <input type="email" name="email" value={formData.email} onChange={handleChange} required className="w-full border rounded p-2" />
              </div>
            </motion.div>
          )}

          {step === 2 && (
            <motion.div
              key="step2"
              initial={{ opacity: 0, x: -30 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: 30 }}
              transition={{ duration: 0.3 }}
              className="space-y-4"
            >
              <div>
                <label className="block">Téléphone *</label>
                <input type="text" name="telephone" value={formData.telephone} onChange={handleChange} required className="w-full border rounded p-2" />
              </div>
              <div>
                <label className="block">Lien (portfolio, LinkedIn...) *</label>
                <input type="url" name="lien" value={formData.lien} onChange={handleChange} required className="w-full border rounded p-2" />
              </div>
              <div>
                <label className="block">Commentaire (facultatif)</label>
                <textarea name="commentaire" value={formData.commentaire} onChange={handleChange} className="w-full border rounded p-2" rows={3} />
              </div>
            </motion.div>
          )}

          {step === 3 && (
            <motion.div
              key="step3"
              initial={{ opacity: 0, x: -30 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: 30 }}
              transition={{ duration: 0.3 }}
              className="space-y-4"
            >
              <div>
                <label className="block">CV (PDF) *</label>
                <input type="file" name="cv" accept=".pdf" onChange={handleChange} required />
                {renderFilePreview(formData.cv)}
              </div>
              <div>
                <label className="block">Lettre de motivation (PDF) *</label>
                <input type="file" name="lettre" accept=".pdf" onChange={handleChange} required />
                {renderFilePreview(formData.lettre)}
              </div>
              <div>
                <label className="block">Diplôme (PDF) *</label>
                <input type="file" name="diplome" accept=".pdf" onChange={handleChange} required />
                {renderFilePreview(formData.diplome)}
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        {/* 🧭 Navigation */}
        <div className="flex justify-between items-center mt-4">
          {step > 1 && (
            <button
              type="button"
              onClick={() => setStep(step - 1)}
              className="px-4 py-2 bg-gray-300 hover:bg-gray-400 rounded"
            >
              ◀ Précédent
            </button>
          )}
          {step < 3 ? (
            <button
              type="button"
              onClick={() => validateStep() && setStep(step + 1)}
              className="ml-auto px-4 py-2 bg-red-700 text-white rounded hover:bg-red-800"
            >
              Suivant ▶
            </button>
          ) : (
            <button
              type="submit"
              disabled={loading}
              className="ml-auto px-4 py-2 bg-green-600 text-white rounded hover:bg-green-700"
            >
              {loading ? "Envoi..." : "Envoyer la candidature"}
            </button>
          )}
        </div>
      </form>
    </div>
  );
}
