import { useParams, useNavigate } from "react-router-dom";
import { useEffect, useState, useRef } from "react";
import { motion, AnimatePresence } from "framer-motion";
import api from "@/utils/api";
import {
  ArrowLeft,
  Printer,
  Copy,
  Download,
  Briefcase,
  User,
  Calendar,
  Globe,
  FileText,
  ClipboardList,
  CheckCircle2,
  GraduationCap,
  MapPin,
  Building2,
} from "lucide-react";

export default function OffreDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [offre, setOffre] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const contentRef = useRef();

  useEffect(() => {
    const fetchOffre = async () => {
      try {
        const res = await api.get(`/recrutement/${id}`);
        setOffre(res.data);
      } catch {
        setError("Offre introuvable");
      } finally {
        setLoading(false);
      }
    };
    fetchOffre();
  }, [id]);

  const sections = [
    { key: "description", label: "Description", icon: <FileText size={18} /> },
    { key: "resume", label: "Résumé", icon: <ClipboardList size={18} /> },
    { key: "attributions", label: "Attributions", icon: <CheckCircle2 size={18} /> },
    { key: "competences", label: "Compétences", icon: <CheckCircle2 size={18} /> },
    { key: "formation", label: "Formation", icon: <GraduationCap size={18} /> },
    { key: "experience", label: "Expérience", icon: <Briefcase size={18} /> },
    { key: "certifications", label: "Certifications", icon: <CheckCircle2 size={18} /> },
    { key: "logiciels", label: "Logiciels", icon: <CheckCircle2 size={18} /> },
    { key: "affiliations", label: "Affiliations", icon: <CheckCircle2 size={18} /> },
  ];

  const formatDate = (dateStr) => {
    return new Date(dateStr).toLocaleDateString("fr-FR", {
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    });
  };

  const handleCopy = () => {
    const text = `${offre.titre} - ${offre.lieu}`;
    navigator.clipboard.writeText(text);
    alert("Offre copiée !");
  };

  if (loading) return <p className="text-center py-10">Chargement...</p>;
  if (error) return <p className="text-center text-red-500 py-10">{error}</p>;

  return (
    <div className="flex flex-col lg:flex-row px-4 py-10 max-w-6xl mx-auto">
      {/* 🔗 Sidebar sticky */}
      <aside className="lg:w-1/4 mb-6 lg:mb-0 lg:pr-6 sticky top-20 self-start hidden lg:block">
        <h3 className="text-lg font-bold mb-4">📌 Navigation</h3>
        <ul className="space-y-2 text-sm">
          {sections.map((section) =>
            offre[section.key] ? (
              <li key={section.key}>
                <a
                  href={`#${section.key}`}
                  className="hover:underline text-blue-600 flex items-center gap-2"
                >
                  {section.icon}
                  {section.label}
                </a>
              </li>
            ) : null
          )}
        </ul>
      </aside>

      {/* 📄 Contenu principal */}
      <div className="lg:w-3/4 w-full space-y-6 mt-20" ref={contentRef}>
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 gap-4">
          <h1 className="text-3xl font-bold text-red-700">{offre.titre}</h1>
          <div className="flex flex-wrap gap-2">
            <button
              onClick={() => navigate("/offres")}
              className="bg-blue-600 text-white px-3 py-1 rounded text-sm hover:bg-blue-700"
            >
              <ArrowLeft size={16} className="inline mr-1" /> Retour aux offres
            </button>
            <button onClick={() => window.print()} className="px-3 py-1 bg-gray-100 hover:bg-gray-200 text-gray-700 rounded text-sm flex items-center gap-1">
              <Printer size={16} /> Imprimer
            </button>
            <button onClick={handleCopy} className="px-3 py-1 bg-gray-100 hover:bg-gray-200 text-gray-700 rounded text-sm flex items-center gap-1">
              <Copy size={16} /> Copier l’offre
            </button>
          </div>
        </div>

        {/* 📌 Métadonnées */}
        <ul className="text-gray-600 space-y-1 text-sm">
          <li className="flex items-center gap-2">
            <MapPin size={16} /> {offre.lieu}
          </li>
          <li className="flex items-center gap-2">
            <Building2 size={16} /> {offre.employeur}
          </li>
          <li className="flex items-center gap-2">
            <Calendar size={16} /> Date limite : <strong>{formatDate(offre.date_limite)}</strong>
          </li>
          <li className="flex items-center gap-2">
            <User size={16} /> État :{" "}
            <span className={offre.etat === "Expiré" ? "text-red-600 font-semibold" : "text-green-600 font-semibold"}>
              {offre.etat}
            </span>
          </li>
        </ul>

        {/* 🔽 Sections dynamiques */}
        {sections.map((section) =>
          offre[section.key] ? (
            <details key={section.key} id={section.key} className="border rounded-md p-4 group" open>
              <summary className="font-semibold text-lg cursor-pointer flex items-center gap-2">
                {section.icon}
                {section.label}
              </summary>
              <AnimatePresence initial={false}>
                <motion.div
                  key={section.key}
                  initial={{ height: 0, opacity: 0 }}
                  animate={{ height: "auto", opacity: 1 }}
                  exit={{ height: 0, opacity: 0 }}
                  transition={{ duration: 0.3 }}
                  className="overflow-hidden mt-2"
                >
                  <p className="text-gray-700 whitespace-pre-line">{offre[section.key]}</p>
                </motion.div>
              </AnimatePresence>
            </details>
          ) : null
        )}

        {/* ✅ Boutons action */}
        <div className="mt-8 flex flex-col sm:flex-row gap-4">
          <button
            onClick={() => navigate(`/postuler/${id}`)}
            disabled={offre.etat === "Expiré"}
            className={`font-bold py-2 px-6 rounded ${
              offre.etat === "Expiré"
                ? "bg-gray-400 text-white cursor-not-allowed"
                : "bg-red-700 hover:bg-red-800 text-white"
            }`}
          >
            {offre.etat === "Expiré" ? "Offre expirée" : "Postuler maintenant"}
          </button>

          {offre.etat === "Expiré" && (
            <p className="text-sm text-red-600 mt-1">La période de candidature est terminée.</p>
          )}

          {offre.document_url && (
            <a
              href={offre.document_url}
              target="_blank"
              rel="noopener noreferrer"
              className="bg-gray-100 hover:bg-gray-200 text-gray-700 font-medium py-2 px-6 rounded flex items-center gap-2"
            >
              <Download size={18} /> Télécharger l’offre originale (PDF)
            </a>
          )}
        </div>
      </div>
    </div>
  );
}
