//pages/public/Offres.jsx

import { useEffect, useState } from "react";
import jsPDF from "jspdf";
import "jspdf-autotable";
import api from "@/utils/api";

export default function Offres() {
  const [offres, setOffres] = useState([]);
  const [lieu, setLieu] = useState("");
  const [employeur, setEmployeur] = useState("");
  const [typeContrat, setTypeContrat] = useState("");
  const [dateMin, setDateMin] = useState("");
  const [dateMax, setDateMax] = useState("");
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const limit = 3;

  const fetchOffres = async () => {
    const params = new URLSearchParams({
      page,
      limit,
      lieu,
      employeur,
      type_contrat: typeContrat,
      date_min: dateMin,
      date_max: dateMax,
    });

    try {
      const res = await api.get("/offres", { params });
      const data = res.data;

      if (Array.isArray(data.offres)) {
        setOffres(data.offres);
        setTotalPages(data.totalPages);
      } else {
        console.error("Format inattendu :", data);
        setOffres([]);
      }
    } catch (err) {
      console.error("Erreur chargement des offres :", err);
      setOffres([]);
    }
  };

  useEffect(() => {
    fetchOffres();
  }, [page, lieu, employeur, typeContrat, dateMin, dateMax]);

  const resetFilters = () => {
    setLieu("");
    setEmployeur("");
    setTypeContrat("");
    setDateMin("");
    setDateMax("");
    setPage(1);
  };

  const exportPDF = () => {
    const doc = new jsPDF();
    doc.text("Offres d'emploi", 14, 10);
    doc.autoTable({
      head: [["Titre", "Lieu", "Employeur", "Contrat"]],
      body: (Array.isArray(offres) ? offres : []).map((o) => [
        o.titre,
        o.lieu,
        o.employeur,
        o.type_contrat,
      ]),
    });
    doc.save("offres.pdf");
  };

  return (
    <div className="max-w-6xl mx-auto px-4 pt-20 pb-28 relative">
      <h1 className="text-2xl font-bold text-center text-red-700 mb-4">Offres d'emploi</h1>

      {/* Filtres */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-3 mb-4">
        <input
          type="text"
          placeholder="Filtrer par lieu"
          value={lieu}
          onChange={(e) => { setPage(1); setLieu(e.target.value); }}
          className="border px-3 py-2 rounded"
        />
        <input
          type="text"
          placeholder="Filtrer par employeur"
          value={employeur}
          onChange={(e) => { setPage(1); setEmployeur(e.target.value); }}
          className="border px-3 py-2 rounded"
        />
        <input
          type="text"
          placeholder="Filtrer par type_contrat"
          value={typeContrat}
          onChange={(e) => { setPage(1); setTypeContrat(e.target.value); }}
          className="border px-3 py-2 rounded"
        />
      </div>

      {/* Filtres dates */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-3 mb-4">
        <input
          type="date"
          value={dateMin}
          onChange={(e) => { setPage(1); setDateMin(e.target.value); }}
          className="border px-3 py-2 rounded"
        />
        <input
          type="date"
          value={dateMax}
          onChange={(e) => { setPage(1); setDateMax(e.target.value); }}
          className="border px-3 py-2 rounded"
        />
        <button
          onClick={resetFilters}
          className="bg-gray-300 text-gray-800 px-3 py-2 rounded hover:bg-gray-400"
        >
          ♻️ Réinitialiser
        </button>
      </div>

      {/* Export */}
      <div className="flex justify-end mb-4">
        <button
          onClick={exportPDF}
          className="bg-red-600 text-white px-4 py-2 rounded hover:bg-red-700"
        >
          📄 Exporter en PDF
        </button>
      </div>

      {/* Offres */}
      {(Array.isArray(offres) && offres.length > 0) ? (
        offres.map((offre) => (
          <div key={offre.id} className="bg-white border rounded p-4 mb-4">
            <h2 className="text-lg font-bold text-red-700">{offre.titre}</h2>
            <p className="text-sm italic text-gray-600 mb-2">Recrutement Externe</p>
              <div className="flex flex-wrap justify-between text-sm items-center">
                <span><strong>Lieu:</strong> {offre.lieu}</span>
                <span><strong>Employeur:</strong> {offre.employeur}</span>
                <span><strong>Contrat:</strong> {offre.type_contrat}</span>
                <span
                  className={`px-2 py-1 rounded text-white font-semibold ${
                    offre.etat === "Actif" ? "bg-green-600" : "bg-gray-500"
                  }`}
                >
                  {offre.etat}
                </span>
              </div>
            <div className="mt-3 text-right">
              <a
                href={`/offre/${offre.id}`}
                className="bg-red-600 text-white px-4 py-1 rounded hover:bg-red-700"
              >
                Voir l'offre
              </a>
            </div>
          </div>
        ))
      ) : (
        <p className="text-center text-gray-500">Aucune offre trouvée.</p>
      )}

      {/* Pagination */}
      <div className="flex justify-center items-center space-x-2 mt-6">
        <button
          onClick={() => setPage((p) => Math.max(1, p - 1))}
          disabled={page <= 1}
          className="px-3 py-1 border rounded disabled:opacity-50"
        >
          Précédent
        </button>
        {[...Array(totalPages)].map((_, idx) => (
          <button
            key={idx + 1}
            onClick={() => setPage(idx + 1)}
            className={`px-3 py-1 border rounded ${page === idx + 1 ? "bg-red-600 text-white" : ""}`}
          >
            {idx + 1}
          </button>
        ))}
        <button
          onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
          disabled={page >= totalPages}
          className="px-3 py-1 border rounded disabled:opacity-50"
        >
          Suivant
        </button>
      </div>
    </div>
  );
}
